EOD;

// ================================================================
// 2. CONFIGURACIÓN Y PROCESAMIENTO
// ================================================================
$conexion->begin_transaction();

try {
    // ----------------------------------------------------------------
    // 2a. Crear secciones para todos los grados (sala + 'U')
    // ----------------------------------------------------------------
    $mapeo_salas = [
        'Sala de 5' => 'sala5',
        '1er Grado' => '1ro',
        '2do Grado' => '2do',
        '3er Grado' => '3ro',
        '4to Grado' => '4to',
        '5to Grado' => '5to',
        '6to Grado' => '6to',
    ];
    $secciones = [];
    foreach ($mapeo_salas as $nombre_sala => $codigo_sala) {
        $stmt = $conexion->prepare("SELECT id FROM secciones WHERE sala = ? AND nombre = 'U'");
        $stmt->bind_param('s', $codigo_sala);
        $stmt->execute();
        $res = $stmt->get_result();
        if ($res->num_rows == 0) {
            $stmt2 = $conexion->prepare("INSERT INTO secciones (nombre, sala) VALUES ('U', ?)");
            $stmt2->bind_param('s', $codigo_sala);
            $stmt2->execute();
            $id_nuevo = $conexion->insert_id;
            echo "Creada sección: $nombre_sala (U) ID=$id_nuevo\n";
        } else {
            $fila = $res->fetch_assoc();
            $id_nuevo = $fila['id'];
            echo "Sección ya existe: $nombre_sala (U) ID=$id_nuevo\n";
        }
        $secciones[$codigo_sala] = $id_nuevo;
    }

    // ----------------------------------------------------------------
    // 2b. Funciones auxiliares
    // ----------------------------------------------------------------
    function obtenerRepresentante($cedula, $nombre, $telefono, $conexion) {
        if (empty($cedula) || empty($nombre)) return null;
        $cedula = trim($cedula);
        $nombre = trim($nombre);
        $telefono = preg_replace('/[^0-9]/', '', trim($telefono));
        $stmt = $conexion->prepare("SELECT id FROM representantes WHERE cedula = ?");
        $stmt->bind_param('s', $cedula);
        $stmt->execute();
        $res = $stmt->get_result();
        if ($fila = $res->fetch_assoc()) return $fila['id'];
        $stmt = $conexion->prepare("INSERT INTO representantes (nombre_completo, cedula, telefono, parentesco, nacionalidad) VALUES (?, ?, ?, 'Tutor Legal', 'Venezolana')");
        $stmt->bind_param('sss', $nombre, $cedula, $telefono);
        $stmt->execute();
        return $conexion->insert_id;
    }

    function obtenerProfesor($nombre_completo, $conexion) {
        if (empty($nombre_completo)) return null;
        $partes = explode(' ', trim($nombre_completo));
        $apellido = array_pop($partes);
        $nombre = implode(' ', $partes);
        $stmt = $conexion->prepare("SELECT id FROM profesores WHERE nombre = ? AND apellido = ?");
        $stmt->bind_param('ss', $nombre, $apellido);
        $stmt->execute();
        $res = $stmt->get_result();
        if ($fila = $res->fetch_assoc()) return $fila['id'];
        $usuario = strtolower(str_replace(' ', '_', $nombre_completo));
        $password = password_hash('12345', PASSWORD_DEFAULT);
        $stmt = $conexion->prepare("INSERT INTO profesores (nombre, apellido, usuario, password, rol, estatus) VALUES (?, ?, ?, ?, 'profesor', 'Activo')");
        $stmt->bind_param('ssss', $nombre, $apellido, $usuario, $password);
        $stmt->execute();
        return $conexion->insert_id;
    }

    // ----------------------------------------------------------------
    // 2c. Procesar cada línea
    // ----------------------------------------------------------------
    $lineas = explode("\n", trim($datos));
    $contador = 0;
    $errores = 0;

    foreach ($lineas as $linea) {
        $linea = trim($linea);
        if (empty($linea)) continue;
        $campos = explode("\t", $linea);
        if (count($campos) < 18) {
            echo "Línea incompleta (".count($campos)." campos): $linea\n";
            $errores++;
            continue;
        }

        // Asignación manual (sin spread)
        $cedula_escolar = trim($campos[0]);
        $nombre_completo = trim($campos[1]);
        $genero_texto   = trim($campos[2]);
        $fecha_nac_str  = trim($campos[3]);
        $pais_nac       = trim($campos[4]);
        $nacionalidad   = trim($campos[5]);
        $direccion      = trim($campos[7]);
        $sala_texto     = trim($campos[8]);
        $estatus_texto  = trim($campos[10]);
        $ano_escolar    = trim($campos[11]);
        $peso           = trim($campos[12]);
        $talla          = trim($campos[13]);
        $inscripto      = trim($campos[14]);
        $rep_cedula     = trim($campos[15]);
        $rep_nombre     = trim($campos[16]);
        $rep_telefono   = trim($campos[17]);

        // Detectar docente (buscar desde el final)
        $docente_nombre = '';
        for ($i = count($campos) - 1; $i >= 0; $i--) {
            $posible = trim($campos[$i]);
            if (!empty($posible) && preg_match('/^[A-Za-záéíóúñÑ\s]+$/', $posible) &&
                (stripos($posible, 'Maria') !== false || stripos($posible, 'Angela') !== false ||
                 stripos($posible, 'Rosa') !== false || stripos($posible, 'Sandra') !== false ||
                 stripos($posible, 'Silvia') !== false || stripos($posible, 'Keila') !== false ||
                 stripos($posible, 'Mayra') !== false)) {
                $docente_nombre = $posible;
                break;
            }
        }

        // Fallback: si no se detectó, usar campos fijos (23, 22, 21)
        if (empty($docente_nombre) && isset($campos[23])) $docente_nombre = trim($campos[23]);
        if (empty($docente_nombre) && isset($campos[22])) $docente_nombre = trim($campos[22]);
        if (empty($docente_nombre) && isset($campos[21])) $docente_nombre = trim($campos[21]);

        // Validar fecha
        $fecha_nac = DateTime::createFromFormat('d/m/Y', $fecha_nac_str);
        if (!$fecha_nac) {
            echo "Fecha inválida: $fecha_nac_str para $nombre_completo\n";
            $errores++;
            continue;
        }
        $fecha_nac = $fecha_nac->format('Y-m-d');

        // Separar nombre y apellido
        $partes = explode(' ', $nombre_completo);
        $apellido = array_pop($partes);
        $nombre = implode(' ', $partes);

        $genero = (stripos($genero_texto, 'FEMENINO') !== false) ? 'H' : 'V';
        $nacionalidad = (stripos($nacionalidad, 'VENEZOLANO') !== false) ? 'Venezolana' : 'Extranjero';
        $pais_nac = (stripos($pais_nac, 'VENEZUELA') !== false) ? 'Venezuela' : $pais_nac;

        $sala_codigo = $mapeo_salas[$sala_texto] ?? null;
        if (!$sala_codigo) {
            echo "Sala desconocida: $sala_texto para $nombre_completo\n";
            $errores++;
            continue;
        }
        $seccion_id = $secciones[$sala_codigo] ?? null;
        if (!$seccion_id) {
            echo "No se encontró sección para $sala_codigo\n";
            $errores++;
            continue;
        }

        $estatus = (stripos($inscripto, 'Inscripto') !== false) ? 'Activo' : 'Inactivo';
        if (stripos($estatus_texto, 'Retirado') !== false) $estatus = 'Inactivo';

        $anio_inicio = substr($ano_escolar, 0, 4);
        $fecha_ingreso = date('Y-m-d', strtotime("first day of July $anio_inicio"));

        $peso = floatval(str_replace(',', '.', $peso));
        $talla = floatval(str_replace(',', '.', $talla));

        // Insertar representante
        $representante_id = null;
        if (!empty($rep_cedula) && !empty($rep_nombre)) {
            $representante_id = obtenerRepresentante($rep_cedula, $rep_nombre, $rep_telefono, $conexion);
        }

        // Insertar profesor
        $docente_id = null;
        if (!empty($docente_nombre)) {
            $docente_id = obtenerProfesor($docente_nombre, $conexion);
        }

        // Verificar duplicado por cédula escolar
        $stmt = $conexion->prepare("SELECT id FROM estudiantes WHERE cedula_escolar = ?");
        $stmt->bind_param('s', $cedula_escolar);
        $stmt->execute();
        $res = $stmt->get_result();
        if ($res->num_rows > 0) {
            echo "Estudiante ya existe (C.E. $cedula_escolar): $nombre $apellido\n";
            continue;
        }

        // Insertar estudiante
        $stmt = $conexion->prepare("INSERT INTO estudiantes 
            (nombre, apellido, cedula_escolar, fecha_nacimiento, genero, nacionalidad, pais_nacimiento, direccion, sala, seccion_id, estatus, fecha_ingreso, rep_nombre, rep_cedula, rep_telefono, representante_id) 
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)");
        $stmt->bind_param(
            'ssssssssiissssi',
            $nombre,
            $apellido,
            $cedula_escolar,
            $fecha_nac,
            $genero,
            $nacionalidad,
            $pais_nac,
            $direccion,
            $sala_codigo,
            $seccion_id,
            $estatus,
            $fecha_ingreso,
            $rep_nombre,
            $rep_cedula,
            $rep_telefono,
            $representante_id
        );
        $stmt->execute();
        $contador++;
        echo "Insertado: $nombre $apellido (C.E. $cedula_escolar)\n";
    }

    $conexion->commit();
    echo "\n✅ ¡Inscripción completada con éxito!\n";
    echo "Total estudiantes insertados: $contador\n";
    echo "Total errores: $errores\n";

} catch (Exception $e) {
    $conexion->rollback();
    echo "❌ Error: " . $e->getMessage() . "\n";
    echo "Se ha revertido toda la operación.\n";
}
?>